VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,7.31,"Algorithms, phase two. Search and routing. This is how maps and the internet find the way."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":21.687,"caps":[[0.5,3.95,"A map is places joined by roads."],[4.2,8.45,"Each road has a cost. A route adds them up."],[8.7,15.59,"The fewest roads is not always the cheapest."],[15.84,20.09,"There are 7 routes. We need a method."]],"warp":[[0,0],[0.5,0.4],[4.2,3.4],[8.7,6.4],[15.84,9.2],[21.687,11]]},{"dur":26.657,"caps":[[0.5,4.67,"Distance from A. Settle the smallest first."],[4.92,11.57,"Then check its roads. A shorter way replaces the old distance."],[11.82,20.71,"Repeat. The smallest waiting (tentative) distance is always final."],[20.96,25.61,"The green roads are the shortest routes: A to E costs 8."]],"warp":[[0,0],[0.5,0.4],[4.92,2.4],[11.82,8.15],[20.96,14.75],[26.657,18.5]]},{"dur":21.734,"caps":[[0.5,5.47,"Any other way to C goes via B, and B is already further."],[5.72,8.85,"So the smallest waiting node is final."],[9.1,15.91,"A negative road can undercut a node that was settled."],[16.16,19.93,"So Dijkstra needs roads with no negative cost."]],"warp":[[0,0],[0.5,0.4],[5.72,4.8],[9.1,6.8],[16.16,9.8],[21.734,12]]},{"dur":28.305,"caps":[[0.5,4.91,"Same search, on a grid: every step costs 1."],[5.16,12.53,"A* adds a compass: score = cost so far g + a guess h."],[12.78,17.03,"h counts the cells to the goal, ignoring the wall."],[17.28,23.21,"It tries the lowest f first: straight at the goal, then round the wall."],[23.46,26.83,"It finds the way round the wall: cost 11."]],"warp":[[0,0],[0.5,0.4],[5.16,2.5],[12.78,4.6],[17.28,6.6],[23.46,12.4],[28.305,15]]},{"dur":24.961,"caps":[[0.5,7.15,"Same grid, same wall. Dijkstra looks everywhere."],[7.4,14.05,"A* aims at the goal and expands far fewer cells."],[14.3,18.79,"But its guess must never be higher than the true cost left."],[19.04,24.09,"A guess that is too high can fool A*."]],"warp":[[0,0],[0.5,0.4],[7.4,3.4],[14.3,7.5],[19.04,10.2],[24.961,12.4]]},{"dur":26.657,"caps":[[0.5,5.15,"Routers are the places. Every router learns the whole map."],[5.4,9.97,"Each runs Dijkstra and keeps only the first hop."],[10.22,14.87,"A packet for F. A's table says: next hop D."],[15.12,19.05,"D has its own table: next hop E."],[19.3,25.39,"E's table: F is one hop away. Every router uses its own table."]],"warp":[[0,0],[0.5,0.4],[5.4,3.2],[10.22,7.4],[15.12,8.8],[19.3,10.4],[26.657,13.5]]},{"dur":20.015,"caps":[[0.5,6.99,"A sees only its neighbours. Each one says how far F is."],[7.24,13.41,"A adds its own road cost to each answer."],[13.66,18.15,"It keeps the smallest total, and the next hop: D."]],"warp":[[0,0],[0.5,0.4],[7.24,4.2],[13.66,7.4],[20.015,12]]},{"dur":31.765,"caps":[[0.5,6.75,"A reaches C through B. B reaches C directly."],[7,13.25,"The B to C road breaks. B hears A's old news."],[13.5,20.71,"The cost creeps up, one step at a time."],[20.96,24.09,"Same story again, with one change."],[24.34,30.99,"Poisoned reverse: A says C is unreachable, because its route goes through B."]],"warp":[[0,0],[0.5,0.4],[7,3],[13.5,6.8],[20.96,9.7],[24.34,11],[31.765,15]]},{"dur":18.437,"caps":[],"warp":[[0,0],[0.5,0.9],[5.88,2],[12.06,3.1],[18.437,9]]}]};
